import {
    Card,
    CardContent,
    CardDescription,
    CardHeader,
    CardTitle,
  } from '@/components/ui/card';
  import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
  } from '@/components/ui/table';
  import { Badge } from '@/components/ui/badge';
  import { donations } from '@/lib/data';
  import { Button } from '@/components/ui/button';
  import Link from 'next/link';
  
  // Filter donations for a specific user to simulate a logged-in donor view
  const userDonations = donations.filter(d => d.email === 'alice@example.com');
  const totalDonated = userDonations.reduce((acc, d) => acc + d.amount, 0);
  
  export default function DonorDashboardPage() {
    return (
      <div className="grid gap-6">
        <div className="grid gap-4 md:grid-cols-2">
          <Card>
            <CardHeader>
              <CardTitle>Total Donated</CardTitle>
              <CardDescription>Thank you for your generosity!</CardDescription>
            </CardHeader>
            <CardContent>
              <p className="text-3xl font-bold">${totalDonated.toLocaleString()}</p>
            </CardContent>
          </Card>
          <Card className="flex flex-col items-center justify-center bg-secondary">
            <CardHeader>
                <CardTitle>Make a New Donation</CardTitle>
                <CardDescription>Your support is invaluable.</CardDescription>
            </CardHeader>
            <CardContent>
                <Button asChild size="lg">
                    <Link href="/donate">Donate Now</Link>
                </Button>
            </CardContent>
          </Card>
        </div>
        
        <Card>
          <CardHeader>
            <CardTitle className="font-headline">Your Donation History</CardTitle>
            <CardDescription>A record of your contributions.</CardDescription>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Date</TableHead>
                  <TableHead>Campaign</TableHead>
                  <TableHead className="text-right">Amount</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {userDonations.map((donation) => (
                  <TableRow key={donation.id}>
                    <TableCell>
                      {new Date(donation.date).toLocaleDateString()}
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline">{donation.campaign}</Badge>
                    </TableCell>
                    <TableCell className="text-right">
                      ${donation.amount.toFixed(2)}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      </div>
    );
  }
  